"""Monte Carlo pi estimate CPU fixture."""

import cupy as cp


def run(n_samples: int = 10000) -> float:
    x = cp.random.uniform(size=n_samples)
    y = cp.random.uniform(size=n_samples)
    inside = x * x + y * y <= 1.0
    return float(4.0 * cp.mean(inside))


if __name__ == "__main__":
    print(run())
